WITH PARAMS AS ( SELECT CASE WHEN LEFT(TRIM(COALESCE(:VAR_DATA_INICIO, '')), 10) REGEXP '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN STR_TO_DATE(LEFT(TRIM(:VAR_DATA_INICIO), 10), '%d/%m/%Y') WHEN LEFT(TRIM(COALESCE(:VAR_DATA_INICIO, '')), 10) REGEXP '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN DATE(LEFT(TRIM(:VAR_DATA_INICIO), 10)) ELSE NULL END AS DT_INI_IN, CASE WHEN LEFT(TRIM(COALESCE(:VAR_DATA_FIM, '')), 10) REGEXP '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN STR_TO_DATE(LEFT(TRIM(:VAR_DATA_FIM), 10), '%d/%m/%Y') WHEN LEFT(TRIM(COALESCE(:VAR_DATA_FIM, '')), 10) REGEXP '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN DATE(LEFT(TRIM(:VAR_DATA_FIM), 10)) ELSE NULL END AS DT_FIM_IN ), D AS ( SELECT LEAST(DT_INI, DT_FIM) AS DT_INI, GREATEST(DT_INI, DT_FIM) AS DT_FIM, YEAR(GREATEST(DT_INI, DT_FIM)) AS ANO_ATU, YEAR(GREATEST(DT_INI, DT_FIM)) - 1 AS ANO_ANT, DATE_SUB(LEAST(DT_INI, DT_FIM), INTERVAL 1 YEAR) AS DT_INI_ANT, DATE_SUB(GREATEST(DT_INI, DT_FIM), INTERVAL 1 YEAR) AS DT_FIM_ANT FROM ( SELECT COALESCE(DT_FIM_IN, CURDATE()) AS DT_FIM, COALESCE(DT_INI_IN, MAKEDATE(YEAR(COALESCE(DT_FIM_IN, CURDATE())), 1)) AS DT_INI FROM PARAMS ) X ), res AS ( SELECT SUM(CASE WHEN DATE(REFERENCIA) BETWEEN (SELECT DT_INI FROM D) AND (SELECT DT_FIM FROM D) THEN VLRLANC ELSE 0 END) AS V_ATU, SUM(CASE WHEN DATE(REFERENCIA) BETWEEN (SELECT DT_INI_ANT FROM D) AND (SELECT DT_FIM_ANT FROM D) THEN VLRLANC ELSE 0 END) AS V_ANT FROM IMP_BASE_BALANCETE WHERE CODEMP = :VAR_EMPRESA_DRE AND (CTACTB LIKE '3%' OR CTACTB LIKE '4%' OR CTACTB LIKE '5%') ) SELECT IFNULL((SELECT V_ATU FROM res), 0) AS VALOR_ATUAL, IFNULL((SELECT V_ANT FROM res), 0) AS VALOR_ANTERIOR, (SELECT ANO_ATU FROM D) AS ANO_ATU, (SELECT ANO_ANT FROM D) AS ANO_ANT, (SELECT DT_INI FROM D) AS DATA_INICIO_USADA, (SELECT DT_FIM FROM D) AS DATA_FIM_USADA, (SELECT COUNT(*) FROM IMP_BASE_BALANCETE WHERE CODEMP = :VAR_EMPRESA_DRE) AS LANC_EMPRESA, (SELECT COUNT(*) FROM IMP_BASE_BALANCETE WHERE CODEMP = :VAR_EMPRESA_DRE AND DATE(REFERENCIA) BETWEEN (SELECT DT_INI FROM D) AND (SELECT DT_FIM FROM D)) AS LANC_PERIODO, CASE WHEN (SELECT DT_INI_IN FROM PARAMS) IS NULL OR (SELECT DT_FIM_IN FROM PARAMS) IS NULL THEN 0 ELSE 1 END AS DATAS_OK FROM DUAL;